{
  "items": [
    {
      "name": "strictMono_div_right_of_pos",
      "module_name": "Mathlib.Algebra.Order.Field.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : Semifield α] [inst_1 : PartialOrder α] [PosMulReflectLT α] {a : α},\n  0 < a → StrictMono fun x => x / a"
    },
    {
      "name": "Mathlib.Tactic.LinearCombination.div_lt_const",
      "module_name": "Mathlib.Tactic.LinearCombination.Lemmas",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {b c : α} [inst : Semifield α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α],\n  b < c → ∀ {a : α}, 0 < a → b / a < c / a"
    },
    {
      "name": "OrderedSMul.lt_of_smul_lt_smul_of_pos",
      "module_name": "Mathlib.Algebra.Order.Module.OrderedSMul",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} {inst : Semiring R} {inst_1 : PartialOrder R} {inst_2 : AddCommMonoid M}\n  {inst_3 : PartialOrder M} {inst_4 : SMulWithZero R M} [self : OrderedSMul R M] {a b : M} {c : R},\n  c • a < c • b → 0 < c → a < b"
    },
    {
      "name": "Mathlib.Tactic.LinearCombination.div_le_const",
      "module_name": "Mathlib.Tactic.LinearCombination.Lemmas",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {b c : α} [inst : Semifield α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α],\n  b ≤ c → ∀ {a : α}, 0 ≤ a → b / a ≤ c / a"
    },
    {
      "name": "lt_of_mul_self_lt_mul_self₀",
      "module_name": "Mathlib.Algebra.Order.GroupWithZero.Unbundled.Basic",
      "kind": "theorem",
      "type": "∀ {M₀ : Type u_2} [inst : MonoidWithZero M₀] [inst_1 : LinearOrder M₀] [PosMulStrictMono M₀] {a b : M₀} [MulPosMono M₀],\n  0 ≤ b → a * a < b * b → a < b"
    }
  ]
}

